"use strict";(globalThis.webpackChunkfinadelic=globalThis.webpackChunkfinadelic||[]).push([[445],{445(e,n,i){i.d(n,{default:()=>r});const r='\n      <article id="germanTerms" style="display: none;">\n      <div style="text-align: center; padding-right: 2.3rem;"><strong>Zuletzt aktualisiert:</strong> 01. Juni 2026</div><br>\n      <br>\n         <section class="compPage compPage__artwrap">\n            <h2 class="compPage compPage__title">1. &nbsp;Einleitung und Geltungsbereich</h2>\n            <p class="compPage compPage__paragraph">\n               Diese Nutzungsbedingungen („Terms & Conditions“) regeln die Nutzung der Web‑Applikation <strong>FinaDelic</strong> („Dienst“, „Service“).<br>\n               Durch das Erstellen eines Kontos oder die Nutzung des Dienstes erklären Sie sich mit diesen Bedingungen einverstanden.<br><br>\n               Wenn Sie diesen Bedingungen nicht zustimmen, dürfen Sie den Dienst nicht nutzen.\n            </p><br>\n         </section>\n         <section class="compPage compPage__artwrap">\n            <h2 class="compPage compPage__title">2. &nbsp;Mindestalter und Kontoberechtigung</h2>\n            <p class="compPage compPage__paragraph">\n               <ul>\n                  <li>Die Nutzung von FinaDelic ist ausschließlich Personen ab <strong>18 Jahren</strong> gestattet.</li>\n                  <li>Sie sind verpflichtet, bei der Registrierung korrekte und vollständige Angaben zu machen.</li>\n                  <li>Sie sind für die Sicherheit Ihres Kontos und Ihres Passworts verantwortlich.</li>\n               </ul>\n            </p><br>\n         </section>\n         <section class="compPage compPage__artwrap">\n            <h2 class="compPage compPage__title">3. &nbsp;Art des Dienstes</h2>\n            <p class="compPage compPage__paragraph">\n               FinaDelic ist ein <strong>privates, nicht‑kommerzielles Tool</strong> zur <strong>manuellen Eingabe, Organisation und Visualisierung persönlicher Finanzdaten</strong>.<br><br>\n               Wichtig:<br>\n               <ul>\n                  <li>FinaDelic <strong>importiert keine Daten</strong> von Banken oder Drittanbietern.</li>\n                  <li>FinaDelic <strong>überprüft nicht</strong> die Richtigkeit der eingegebenen Daten.</li>\n                  <li>FinaDelic ist <strong>kein Buchhaltungssystem, keine Steuer‑Software</strong> und <strong>kein Finanzberatungs‑Tool</strong>.</li>\n               </ul><br>\n               <strong>Lokale Speicherung auf Ihrem Gerät.</strong><br>Zur Verbesserung der Ladegeschwindigkeit und Benutzererfahrung speichert FinaDelic bestimmte Daten lokal auf Ihrem Gerät mittels des Browserspeichers („localStorage“). Diese Daten werden nicht an unsere Server übertragen und verbleiben ausschließlich auf Ihrem Gerät.<br>\n            </p><br>\n         </section>\n         <section class="compPage compPage__artwrap">\n            <h2 class="compPage compPage__title">4. &nbsp;Wirtschaftliche Verantwortung (Haftungsausschluss für finanzielle Schäden)</h2>\n            <p class="compPage compPage__paragraph">\n               FinaDelic übernimmt <strong>keine Verantwortung</strong> für:<br>\n               <ul>\n                  <li>finanzielle Verluste,</li>\n                  <li>Fehlentscheidungen,</li>\n                  <li>falsche Berechnungen,</li>\n                  <li>Datenverlust oder Datenkorruption,</li>\n                  <li>wirtschaftliche Schäden jeglicher Art,</li>\n               </ul>\n               die durch die Nutzung des Dienstes entstehen – selbst wenn diese durch Fehler, Ausfälle oder Fehlfunktionen des Dienstes verursacht wurden.<br><br>\n               Der Nutzer ist allein verantwortlich für:<br>\n               <ul>\n                  <li>die <strong>Richtigkeit</strong> seiner eingegebenen Daten,</li>\n                  <li>die <strong>Sicherung</strong> seiner Finanzinformationen,</li>\n                  <li>die <strong>eigene finanzielle Entscheidungsfindung</strong>,</li>\n                  <li>die <strong>Einhaltung gesetzlicher Buchführungspflichten</strong>.</li>\n               </ul><br>\n               FinaDelic empfiehlt ausdrücklich:<br>\n               <ul>\n                  <li><strong>Backups</strong> der eigenen Finanzdaten zu führen,</li>\n                  <li>FinaDelic <strong>nicht als einzige Quelle der Wahrheit</strong> zu verwenden,</li>\n                  <li>keine wirtschaftlichen Entscheidungen ausschließlich auf Basis der App zu treffen.</li>\n               </ul>\n            </p><br>\n         </section>\n         <section class="compPage compPage__artwrap">\n            <h2 class="compPage compPage__title">5. &nbsp;Rechtliche Verantwortung (Verbotene Nutzung)</h2>\n            <p class="compPage compPage__paragraph">\n               Der Nutzer verpflichtet sich, FinaDelic <strong>nicht</strong> zu verwenden für:<br>\n               <ul>\n                  <li>illegale Aktivitäten,</li>\n                  <li>Steuerhinterziehung,</li>\n                  <li>Geldwäsche,</li>\n                  <li>betrügerische Handlungen,</li>\n                  <li>die Umgehung gesetzlicher Pflichten,</li>\n                  <li>die Vorbereitung oder Durchführung strafbarer Handlungen.</li>\n               </ul><br>\n               FinaDelic übernimmt <strong>keine Haftung</strong>, wenn Nutzer den Dienst für rechtswidrige Zwecke verwenden.<br><br>\n               FinaDelic ist <strong>kein Werkzeug zur Gesetzeseinhaltung</strong> und ersetzt keine steuerliche oder rechtliche Beratung.\n            </p><br>\n         </section>\n         <section class="compPage compPage__artwrap">\n            <h2 class="compPage compPage__title">6. &nbsp;Kommerzielle Nutzung</h2>\n            <p class="compPage compPage__paragraph">\n               Die Nutzung von FinaDelic für kommerzielle Zwecke ist grundsätzlich <strong>nicht gestattet</strong>.<br>\n               Dies umfasst insbesondere:<br>\n               <ul>\n                  <li>den Verkauf, die Vermietung oder das Anbieten des Dienstes als Produkt oder Service,</li>\n                  <li>die Nutzung des Dienstes zur Erzielung von Einnahmen,</li>\n                  <li>die Weitergabe oder Bereitstellung des Dienstes an Dritte im Rahmen geschäftlicher Tätigkeiten,</li>\n                  <li>das Kopieren, Klonen oder Reverse Engineering der Anwendung zu kommerziellen Zwecken.</li>\n               </ul><br>\n               <strong>Ausnahme:</strong><br><br>\n               Eine kommerzielle Nutzung ist möglich, <strong>wenn Sie zuvor meine ausdrückliche schriftliche Zustimmung eingeholt haben</strong>.<br><br>\n               Ich behalte mir das Recht vor:\n               <ul>\n                  <li>Anfragen abzulehnen,</li>\n                  <li>Bedingungen festzulegen,</li>\n                  <li>eine Lizenzgebühr oder ein Entgelt zu verlangen,</li>\n                  <li>zusätzliche Anforderungen (z. B. Attribution, Branding, Einschränkungen) zu definieren.</li>\n               </ul><br>\n               Erlaubt bleibt:<br>\n               <ul>\n                  <li>die Nutzung der <strong>selbst erstellten Diagramme</strong> für Präsentationen, Berichte oder berufliche Zwecke, sofern diese Diagramme vom Nutzer selbst erstellt wurden oder er die Erlaubnis des Erstellers besitzt.</li>\n               </ul>\n            </p><br>\n         </section>\n         <section class="compPage compPage__artwrap">\n            <h2 class="compPage compPage__title">7. &nbsp;Verfügbarkeit des Dienstes</h2>\n            <p class="compPage compPage__paragraph">\n               FinaDelic bietet <strong>keine Garantie</strong> für:<br>\n               <ul>\n                  <li>ständige Verfügbarkeit,</li>\n                  <li>fehlerfreien Betrieb,</li>\n                  <li>ununterbrochene Funktionalität,</li>\n                  <li>Datenpersistenz oder Datenwiederherstellung.</li>\n               </ul><br>\n               Der Dienst kann jederzeit:<br>\n               <ul>\n                  <li>aktualisiert,</li>\n                  <li>verändert,</li>\n                  <li>eingeschränkt,</li>\n                  <li>unterbrochen</li>\n               </ul>\n               werden – auch ohne vorherige Ankündigung.\n            </p><br>\n         </section>\n         <section class="compPage compPage__artwrap">\n            <h2 class="compPage compPage__title">8. &nbsp;Kontolöschung und Kündigung</h2>\n            <p class="compPage compPage__paragraph">\n               Sie können Ihr Konto jederzeit löschen.<br><br>\n               Bei Löschung:<br>\n               <ul>\n                  <li>werden alle personenbezogenen und finanziellen Daten <strong>dauerhaft</strong> aus den aktiven Systemen entfernt,</li>\n                  <li>kann der Vorgang <strong>nicht rückgängig gemacht</strong> werden.</li>\n               </ul><br>\n               FinaDelic behält sich das Recht vor, Konten zu sperren oder zu löschen, wenn:<br>\n               <ul>\n                  <li>gegen diese Nutzungsbedingungen verstoßen wird,</li>\n                  <li>der Dienst missbraucht wird,</li>\n                  <li>illegale Aktivitäten vermutet werden.</li>\n               </ul>\n            </p><br>\n         </section>\n         <section class="compPage compPage__artwrap">\n            <h2 class="compPage compPage__title">9. &nbsp;Änderungen der Nutzungsbedingungen</h2>\n            <p class="compPage compPage__paragraph">\n               FinaDelic kann diese Nutzungsbedingungen jederzeit aktualisieren.<br>\n               Bei wesentlichen Änderungen wird ein Hinweis innerhalb der Anwendung angezeigt.<br><br>\n               Die fortgesetzte Nutzung des Dienstes nach Änderungen gilt als Zustimmung zu den aktualisierten Bedingungen.\n            </p><br>\n         </section>\n         <section class="compPage compPage__artwrap">\n            <h2 class="compPage compPage__title">10. &nbsp;Haftungsbeschränkung</h2>\n            <p class="compPage compPage__paragraph">\n               Soweit gesetzlich zulässig, haftet FinaDelic <strong>nicht</strong> für:<br>\n               <ul>\n                  <li>direkte Schäden,</li>\n                  <li>indirekte Schäden,</li>\n                  <li>Folgeschäden,</li>\n                  <li>entgangenen Gewinn,</li>\n                  <li>Datenverlust,</li>\n                  <li>Systemausfälle,</li>\n                  <li>wirtschaftliche Nachteile.</li>\n               </ul><br>\n               Die Nutzung des Dienstes erfolgt <strong>auf eigenes Risiko</strong>.\n            </p><br>\n         </section>\n         <section class="compPage compPage__artwrap">\n            <h2 class="compPage compPage__title">11. &nbsp;Anwendbares Recht</h2>\n            <p class="compPage compPage__paragraph">\n               Diese Nutzungsbedingungen unterliegen dem <strong>österreichischen Recht</strong>.<br>\n               Gerichtsstand ist <strong>Wien</strong>, sofern keine zwingenden gesetzlichen Bestimmungen anderes vorschreiben.\n            </p><br>\n         </section>\n         <section class="compPage compPage__artwrap">\n            <h2 class="compPage compPage__title">12. &nbsp;Kontakt</h2>\n            <p class="compPage compPage__paragraph">\n               Für Fragen zu diesen Nutzungsbedingungen:<br><br>\n               <address style="font-style: normal; line-height: 1.5rem; font-weight: 500;">\n                  <strong>Reinhard Höbart</strong><br>\n                  Kaiser‑Ebersdorfer Straße 87/1<br>\n                  1110 Wien<br>\n                  Österreich<br>\n                  E‑Mail: &nbsp;<strong>info@finadelic.com</strong>\n               </address>\n            </p><br>\n         </section>\n      </article>\n'}}]);